export interface PageMeta {
  title: string;
  date?: Date;
  tags: string[];
  draft: boolean;
  [key: string]: unknown;
}

export interface Page {
  path: string;
  url: string;
  meta: PageMeta;
  content: string;
  raw: string;
}

export interface SiteConfig {
  sourceDir: string;
  outputDir: string;
  templateDir: string;
  siteTitle: string;
  siteUrl: string;
  siteDescription: string;
  port: number;
}

import matter from "gray-matter";
import { PageMeta } from "./types";

export function parseFrontmatter(raw: string): {
  meta: PageMeta;
  content: string;
} {
  const parsed = matter(raw);
  const data = parsed.data as Record<string, unknown>;

  const tags: string[] = (() => {
    const t = data.tags;
    if (Array.isArray(t)) return t.map(String);
    if (typeof t === "string") return t.split(",").map((s: string) => s.trim()).filter(Boolean);
    return [];
  })();

  const draft = typeof data.draft === "boolean" ? data.draft : false;

  let date: Date | undefined;
  if (data.date) {
    date = new Date(data.date as string);
    if (isNaN(date.getTime())) date = undefined;
  }

  const meta: PageMeta = {
    title: (data.title as string) || "Untitled",
    date,
    tags,
    draft,
  };

  for (const key of Object.keys(data)) {
    if (key !== "title" && key !== "date" && key !== "tags" && key !== "draft") {
      meta[key] = data[key];
    }
  }

  return { meta, content: parsed.content };
}

import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";
import { PageMeta } from "./types";

const marked = new Marked(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code: string, lang: string) {
      const language = hljs.getLanguage(lang) ? lang : "plaintext";
      return hljs.highlight(code, { language }).value;
    },
  })
);

marked.setOptions({
  gfm: true,
  breaks: false,
});

export function markdownToHtml(markdown: string): string {
  const result = marked.parse(markdown);
  if (typeof result === "string") return result;
  return "";
}

export { marked };

import Handlebars from "handlebars";
import * as fs from "fs";
import * as path from "path";

export class TemplateEngine {
  private templatesDir: string;
  private partials: Map<string, Handlebars.TemplateDelegate>;
  private layoutTemplate: Handlebars.TemplateDelegate | null;

  constructor(templatesDir: string) {
    this.templatesDir = templatesDir;
    this.partials = new Map();
    this.layoutTemplate = null;
    this.loadPartials();
    this.loadLayout();
    this.registerHelpers();
  }

  private loadPartials(): void {
    const partialsDir = path.join(this.templatesDir, "partials");
    if (!fs.existsSync(partialsDir)) return;

    const files = fs.readdirSync(partialsDir);
    for (const file of files) {
      if (!file.endsWith(".hbs") && !file.endsWith(".handlebars")) continue;
      const name = path.basename(file, path.extname(file));
      const source = fs.readFileSync(path.join(partialsDir, file), "utf-8");
      Handlebars.registerPartial(name, source);
      this.partials.set(name, Handlebars.compile(source));
    }
  }

  private loadLayout(): void {
    const layoutFile = path.join(this.templatesDir, "layout.hbs");
    const altLayoutFile = path.join(this.templatesDir, "layout.handlebars");
    const file = fs.existsSync(layoutFile) ? layoutFile : fs.existsSync(altLayoutFile) ? altLayoutFile : null;

    if (file) {
      const source = fs.readFileSync(file, "utf-8");
      this.layoutTemplate = Handlebars.compile(source);
    }
  }

  private registerHelpers(): void {
    Handlebars.registerHelper("formatDate", (date: Date | string | undefined) => {
      if (!date) return "";
      const d = typeof date === "string" ? new Date(date) : date;
      if (isNaN(d.getTime())) return "";
      return d.toISOString().split("T")[0];
    });

    Handlebars.registerHelper("eq", (a: unknown, b: unknown) => a === b);

    Handlebars.registerHelper("json", (obj: unknown) => {
      return JSON.stringify(obj);
    });
  }

  render(templateName: string, data: Record<string, unknown>): string {
    const content = this.renderContent(templateName, data);

    if (this.layoutTemplate) {
      return this.layoutTemplate({ ...data, body: content, content });
    }

    return content;
  }

  renderString(templateStr: string, data: Record<string, unknown>): string {
    const compiled = Handlebars.compile(templateStr);
    return compiled(data);
  }

  private renderContent(templateName: string, data: Record<string, unknown>): string {
    const file = path.join(this.templatesDir, `${templateName}.hbs`);
    const altFile = path.join(this.templatesDir, `${templateName}.handlebars`);

    const sourcePath = fs.existsSync(file) ? file : fs.existsSync(altFile) ? altFile : null;

    if (!sourcePath) {
      return "";
    }

    const source = fs.readFileSync(sourcePath, "utf-8");
    const compiled = Handlebars.compile(source);
    return compiled(data);
  }

  hasTemplate(name: string): boolean {
    return (
      fs.existsSync(path.join(this.templatesDir, `${name}.hbs`)) ||
      fs.existsSync(path.join(this.templatesDir, `${name}.handlebars`))
    );
  }
}

import { Page, SiteConfig } from "./types";
import { Feed } from "feed";

export function generateRSS(pages: Page[], config: SiteConfig): string {
  const published = pages.filter((p) => !p.meta.draft && p.meta.date);

  const feed = new Feed({
    title: config.siteTitle,
    description: config.siteDescription,
    id: config.siteUrl,
    link: config.siteUrl,
    language: "en",
    updated: published.length > 0 ? published[0].meta.date : new Date(),
    generator: "static-site-gen",
    copyright: "",
    feedLinks: {
      rss2: `${config.siteUrl}/rss.xml`,
    },
  });

  for (const page of published) {
    feed.addItem({
      title: page.meta.title,
      id: `${config.siteUrl}${page.url}`,
      link: `${config.siteUrl}${page.url}`,
      description: page.content.substring(0, 500),
      date: page.meta.date!,
    });
  }

  return feed.rss2();
}

import { Page } from "./types";

export function generateTagIndexes(pages: Page[]): Map<string, Page[]> {
  const byTag = new Map<string, Page[]>();

  for (const page of pages) {
    if (page.meta.draft) continue;
    for (const tag of page.meta.tags) {
      const existing = byTag.get(tag) || [];
      existing.push(page);
      byTag.set(tag, existing);
    }
  }

  return byTag;
}

export function generateTagPageData(
  tag: string,
  tagPages: Page[],
  siteTitle: string
): Record<string, unknown> {
  return {
    title: `Tag: ${tag}`,
    tag,
    pages: tagPages.map((p) => ({
      title: p.meta.title,
      url: p.url,
      date: p.meta.date,
      tags: p.meta.tags,
    })),
    siteTitle,
  };
}

import * as fs from "fs";
import * as path from "path";
import { Page, SiteConfig } from "./types";
import { parseFrontmatter } from "./frontmatter";
import { markdownToHtml } from "./highlight";
import { TemplateEngine } from "./render";
import { generateRSS } from "./rss";
import { generateTagIndexes, generateTagPageData } from "./tags";

export async function build(config: SiteConfig): Promise<void> {
  const pages = discoverPages(config.sourceDir);
  const engine = new TemplateEngine(config.templateDir);

  fs.rmSync(config.outputDir, { recursive: true, force: true });
  fs.mkdirSync(config.outputDir, { recursive: true });

  const published = pages.filter((p) => !p.meta.draft);

  for (const page of published) {
    renderPage(page, pages, published, engine, config);
  }

  renderIndex(published, engine, config);

  const tagIndexes = generateTagIndexes(pages);
  for (const [tag, tagPages] of tagIndexes.entries()) {
    renderTagPage(tag, tagPages, engine, config);
  }

  const rssXml = generateRSS(published, config);
  fs.writeFileSync(path.join(config.outputDir, "rss.xml"), rssXml);
}

function discoverPages(sourceDir: string): Page[] {
  const pages: Page[] = [];

  function walk(dir: string) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(fullPath);
      } else if (entry.name.endsWith(".md")) {
        const raw = fs.readFileSync(fullPath, "utf-8");
        const { meta, content } = parseFrontmatter(raw);
        const relPath = path.relative(sourceDir, fullPath);
        const url = "/" + relPath.replace(/\.md$/, ".html");

        pages.push({ path: fullPath, url, meta, content, raw });
      }
    }
  }

  walk(sourceDir);
  return pages;
}

function renderPage(
  page: Page,
  allPages: Page[],
  published: Page[],
  engine: TemplateEngine,
  config: SiteConfig
): void {
  const html = markdownToHtml(page.content);
  const templateData = {
    ...page.meta,
    title: page.meta.title,
    date: page.meta.date,
    tags: page.meta.tags,
    body: html,
    content: html,
    page,
    pages: published.map(pickPageData),
    siteTitle: config.siteTitle,
    siteUrl: config.siteUrl,
    siteDescription: config.siteDescription,
  };

  let result: string;
  if (engine.hasTemplate("post")) {
    result = engine.render("post", templateData);
  } else {
    result = engine.renderString(
      `<html><head><title>{{title}}</title></head><body>{{{body}}}</body></html>`,
      templateData
    );
  }

  const outPath = path.join(
    config.outputDir,
    page.url.replace(/^\//, "")
  );
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, result);
}

function renderIndex(published: Page[], engine: TemplateEngine, config: SiteConfig): void {
  const data = {
    title: config.siteTitle,
    pages: published.map(pickPageData),
    siteTitle: config.siteTitle,
    siteUrl: config.siteUrl,
    siteDescription: config.siteDescription,
  };

  let result: string;
  if (engine.hasTemplate("index")) {
    result = engine.render("index", data);
  } else {
    const items = published
      .map((p) => `<li><a href="${p.url}">${p.meta.title}</a></li>`)
      .join("");
    result = `<html><head><title>${config.siteTitle}</title></head><body><h1>${config.siteTitle}</h1><ul>${items}</ul></body></html>`;
  }

  fs.writeFileSync(path.join(config.outputDir, "index.html"), result);
}

function renderTagPage(
  tag: string,
  tagPages: Page[],
  engine: TemplateEngine,
  config: SiteConfig
): void {
  const data = generateTagPageData(tag, tagPages, config.siteTitle);

  let result: string;
  if (engine.hasTemplate("tag")) {
    result = engine.render("tag", data);
  } else {
    const items = tagPages
      .map((p) => `<li><a href="${p.url}">${p.meta.title}</a></li>`)
      .join("");
    result = `<html><head><title>Tag: ${tag}</title></head><body><h1>Tag: ${tag}</h1><ul>${items}</ul></body></html>`;
  }

  const outDir = path.join(config.outputDir, "tags");
  fs.mkdirSync(outDir, { recursive: true });
  fs.writeFileSync(path.join(outDir, `${tag}.html`), result);
}

function pickPageData(p: Page) {
  return {
    title: p.meta.title,
    url: p.url,
    date: p.meta.date,
    tags: p.meta.tags,
  };
}

import * as http from "http";
import * as fs from "fs";
import * as path from "path";
import { WebSocketServer, WebSocket } from "ws";
import { watch } from "chokidar";
import { SiteConfig } from "./types";
import { build } from "./build";

const RELOAD_SCRIPT = `
<script>
  (function() {
    var ws = new WebSocket('ws://' + location.host + '/__livereload');
    ws.onmessage = function(msg) {
      if (msg.data === 'reload') {
        location.reload();
      }
    };
    ws.onclose = function() {
      setTimeout(function() {
        var retry = new WebSocket('ws://' + location.host + '/__livereload');
        retry.onmessage = function(msg) {
          if (msg.data === 'reload') location.reload();
        };
      }, 1000);
    };
  })();
</script>
`;

const MIME_TYPES: Record<string, string> = {
  ".html": "text/html",
  ".css": "text/css",
  ".js": "text/javascript",
  ".json": "application/json",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".xml": "application/xml",
  ".txt": "text/plain",
};

export async function startDevServer(config: SiteConfig): Promise<http.Server> {
  await build(config);

  const server = http.createServer((req, res) => {
    const url = req.url || "/";
    let filePath = path.join(config.outputDir, url === "/" ? "index.html" : url);

    if (!path.extname(filePath)) {
      filePath += ".html";
    }

    fs.readFile(filePath, (err, data) => {
      if (err) {
        res.writeHead(404, { "Content-Type": "text/plain" });
        res.end("Not Found");
        return;
      }

      const ext = path.extname(filePath);
      const contentType = MIME_TYPES[ext] || "application/octet-stream";

      if (ext === ".html") {
        const html = data.toString();
        const injected = html.replace("</body>", `${RELOAD_SCRIPT}</body>`);
        res.writeHead(200, { "Content-Type": contentType });
        res.end(injected);
      } else {
        res.writeHead(200, { "Content-Type": contentType });
        res.end(data);
      }
    });
  });

  const wss = new WebSocketServer({ server });

  wss.on("connection", (ws: WebSocket) => {
    ws.on("error", () => {});
  });

  function reload() {
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send("reload");
      }
    }
  }

  const watcher = watch([
    path.join(config.sourceDir, "**", "*.md"),
    path.join(config.templateDir, "**", "*.hbs"),
    path.join(config.templateDir, "**", "*.handlebars"),
  ]);

  let rebuilding = false;

  watcher.on("change", async () => {
    if (rebuilding) return;
    rebuilding = true;
    try {
      await build(config);
      reload();
    } finally {
      rebuilding = false;
    }
  });

  watcher.on("error", () => {});

  return new Promise((resolve) => {
    server.listen(config.port, () => {
      resolve(server);
    });
  });
}

#!/usr/bin/env node

import { Command } from "commander";
import * as path from "path";
import { build } from "./build";
import { startDevServer } from "./server";
import { SiteConfig } from "./types";

const program = new Command();

program
  .name("ssg")
  .description("Static site generator from Markdown files")
  .version("1.0.0");

program
  .command("build")
  .description("Build the static site")
  .requiredOption("-s, --source <dir>", "Source directory of Markdown files")
  .requiredOption("-o, --output <dir>", "Output directory for generated HTML")
  .requiredOption("-t, --templates <dir>", "Template directory with Handlebars templates")
  .option("--title <title>", "Site title", "My Site")
  .option("--url <url>", "Site URL", "http://localhost:8080")
  .option("--description <desc>", "Site description", "")
  .action(async (options) => {
    const config: SiteConfig = {
      sourceDir: path.resolve(options.source),
      outputDir: path.resolve(options.output),
      templateDir: path.resolve(options.templates),
      siteTitle: options.title,
      siteUrl: options.url,
      siteDescription: options.description,
      port: 8080,
    };

    await build(config);
    console.log(`Site built to ${config.outputDir}`);
  });

program
  .command("serve")
  .description("Start dev server with live reload")
  .requiredOption("-s, --source <dir>", "Source directory of Markdown files")
  .requiredOption("-o, --output <dir>", "Output directory for generated HTML")
  .requiredOption("-t, --templates <dir>", "Template directory with Handlebars templates")
  .option("--title <title>", "Site title", "My Site")
  .option("--url <url>", "Site URL", "http://localhost:8080")
  .option("--description <desc>", "Site description", "")
  .option("-p, --port <port>", "Port to listen on", "8080")
  .action(async (options) => {
    const config: SiteConfig = {
      sourceDir: path.resolve(options.source),
      outputDir: path.resolve(options.output),
      templateDir: path.resolve(options.templates),
      siteTitle: options.title,
      siteUrl: options.url,
      siteDescription: options.description,
      port: parseInt(options.port, 10),
    };

    const server = await startDevServer(config);
    console.log(`Dev server running at http://localhost:${config.port}`);
    console.log(`Live reload watching ${config.sourceDir} and ${config.templateDir}`);

    process.on("SIGINT", () => {
      console.log("\nShutting down...");
      server.close();
      process.exit(0);
    });
  });

program.parse(process.argv);

export { SiteConfig, build, startDevServer };

